# Split the string into components
parts = input_str.strip().split('\t')

# Extract fixed columns
chrom = parts[0]
position = parts[1]
ref = parts[2]
alt = parts[3]

# Extract sample=genotype data
sample_data = parts[4:]

# Split each sample=genotype entry
rows = []
for entry in sample_data:
    if '=' in entry:
        sample, genotype = entry.split('=')
        rows.append([chrom, position, ref, alt, sample, genotype])

# Create DataFrame
df = pd.DataFrame(rows, columns=['Chrom', 'Position', 'Ref', 'Alt', 'Sample', 'Genotype'])

# Output or save
print(df.head())
df.to_csv("A675V_longformat.csv", sep=",", index=False)

